#include <iostream>

class Sequencer {
public:
    virtual ~Sequencer() = default;
    virtual int next() = 0;
};

class Doubler : public Sequencer {
public:
    explicit Doubler(int start) : value_(start) {}
    int next() override { value_ *= 2; return value_; }
private:
    int value_;
};

int main() {
    int start = 0;
    int n = 0;
    std::cin >> start >> n;
    Doubler doubler(start);
    Sequencer& seq = doubler;
    int value = start;
    for (int i = 0; i < n; i++) {
        value = seq.next();
    }
    std::cout << value << std::endl;
    return 0;
}
